PRUNE_SQL = "\nCREATE FUNCTION auth.prune_security_events(p_batch_size integer)\nRETURNS TABLE(deleted_count bigint,remaining_expired boolean)\nLANGUAGE plpgsql VOLATILE SECURITY DEFINER SET search_path=pg_catalog AS $function$\nDECLARE\n    v_cutoff timestamptz := transaction_timestamp()-interval '2160 hours';\n    v_count bigint;\n    v_event uuid;\n    v_correlation uuid;\nBEGIN\n    IF NOT (\n        EXISTS (SELECT 1 FROM pg_roles AS login_role\n            WHERE login_role.rolname=session_user AND login_role.rolcanlogin\n              AND NOT login_role.rolsuper AND NOT login_role.rolcreaterole\n              AND NOT login_role.rolcreatedb AND NOT login_role.rolreplication\n              AND NOT login_role.rolbypassrls)\n        AND EXISTS (SELECT 1 FROM pg_roles AS capability\n            WHERE capability.rolname='sahl_security_maintenance' AND NOT capability.rolcanlogin\n              AND NOT capability.rolsuper AND NOT capability.rolcreaterole\n              AND NOT capability.rolcreatedb AND NOT capability.rolreplication\n              AND NOT capability.rolbypassrls\n              AND pg_has_role(session_user,capability.oid,'USAGE'))\n        AND NOT pg_has_role(session_user,'sahl_app','MEMBER')\n        AND NOT pg_has_role(session_user,'sahl_migrator','MEMBER')\n        AND NOT EXISTS (SELECT 1 FROM pg_roles AS reachable\n            WHERE pg_has_role(session_user,reachable.oid,'MEMBER')\n              AND (reachable.rolsuper OR reachable.rolcreaterole OR reachable.rolcreatedb\n                   OR reachable.rolreplication OR reachable.rolbypassrls))\n        AND NOT EXISTS (SELECT 1 FROM pg_database AS d\n            WHERE d.datname=current_database() AND pg_has_role(session_user,d.datdba,'MEMBER'))\n        AND NOT EXISTS (SELECT 1 FROM pg_namespace AS n\n            WHERE n.nspname IN ('auth','app','public')\n              AND (pg_has_role(session_user,n.nspowner,'MEMBER')\n                   OR has_schema_privilege(session_user,n.oid,'CREATE')))\n        AND NOT EXISTS (SELECT 1 FROM pg_class AS c JOIN pg_namespace AS n ON n.oid=c.relnamespace\n            WHERE n.nspname IN ('auth','app','public')\n              AND (pg_has_role(session_user,c.relowner,'MEMBER')\n                   OR CASE WHEN c.relkind IN ('r','p','v','m','f') THEN\n                       has_table_privilege(session_user,c.oid,'SELECT,INSERT,UPDATE,DELETE,TRUNCATE,REFERENCES,TRIGGER')\n                        OR has_any_column_privilege(session_user,c.oid,'SELECT,INSERT,UPDATE,REFERENCES')\n                      WHEN c.relkind='S' THEN has_sequence_privilege(session_user,c.oid,'USAGE,SELECT,UPDATE')\n                      ELSE false END))\n        AND NOT EXISTS (SELECT 1 FROM pg_proc AS p JOIN pg_namespace AS n ON n.oid=p.pronamespace\n            WHERE n.nspname IN ('auth','app','public')\n              AND (pg_has_role(session_user,p.proowner,'MEMBER')\n                   OR (n.nspname='auth' AND p.oid<>'auth.prune_security_events(integer)'::regprocedure\n                       AND has_function_privilege(session_user,p.oid,'EXECUTE'))))\n) THEN\n        RAISE EXCEPTION USING ERRCODE='42501', MESSAGE='audit_retention_denied';\n    END IF;\n    IF p_batch_size IS NULL OR p_batch_size NOT BETWEEN 1 AND 1000 THEN\n        RAISE EXCEPTION USING ERRCODE='22023', MESSAGE='audit_retention_batch_invalid';\n    END IF;\n    WITH expired AS MATERIALIZED (\n        SELECT id FROM auth.security_events WHERE created_at<v_cutoff\n        ORDER BY created_at,id FOR UPDATE SKIP LOCKED LIMIT p_batch_size\n    )\n    DELETE FROM auth.security_events AS event USING expired WHERE event.id=expired.id;\n    GET DIAGNOSTICS v_count=ROW_COUNT;\n    IF v_count>0 THEN\n        v_event := (lpad(to_hex(floor(extract(epoch FROM clock_timestamp())*1000)::bigint),12,'0')\n            ||'7'||substr(replace(gen_random_uuid()::text,'-',''),14))::uuid;\n        v_correlation := gen_random_uuid();\n        PERFORM auth.append_security_event(v_event,'security_events_pruned','success',\n            'retention_expired',NULL,NULL,NULL,NULL,v_correlation,NULL,NULL,NULL,NULL,NULL,v_count);\n    END IF;\n    RETURN QUERY SELECT v_count,EXISTS (\n        SELECT 1 FROM auth.security_events WHERE created_at<v_cutoff\n    );\nEND $function$;\n"


def upgrade() -> None:
    # Provisioning is separate: sahl_migrator has NOCREATEROLE.
    op.execute("""
        DO $check$ BEGIN
            IF NOT EXISTS (SELECT 1 FROM pg_roles WHERE rolname='sahl_security_maintenance'
                AND NOT rolcanlogin AND NOT rolsuper AND NOT rolcreaterole AND NOT rolcreatedb
                AND NOT rolreplication AND NOT rolbypassrls) THEN
                RAISE EXCEPTION USING ERRCODE='42501', MESSAGE='audit_maintenance_role_required';
            END IF;
        END $check$;
    """)
    op.create_index(INDEX_NAME, "security_events", ["created_at", "id"], schema="auth")
    op.execute(PRUNE_SQL)
    op.execute(f"ALTER FUNCTION {PRUNE_SIGNATURE} OWNER TO sahl_migrator")
    op.execute(f"REVOKE ALL ON FUNCTION {PRUNE_SIGNATURE} FROM PUBLIC, sahl_app")
    op.execute(f"GRANT EXECUTE ON FUNCTION {PRUNE_SIGNATURE} TO sahl_security_maintenance")
    op.execute("GRANT USAGE ON SCHEMA auth TO sahl_security_maintenance")
    op.execute(VALIDATOR)
    op.execute("ALTER FUNCTION auth.validate_security_event_insert() OWNER TO sahl_migrator")
    op.execute(
        "REVOKE ALL ON FUNCTION auth.validate_security_event_insert() FROM PUBLIC, sahl_app, sahl_security_maintenance"
    )


def downgrade() -> None:
    # Preserve retained rows, including successful historical prune events.
    op.execute("LOCK TABLE auth.security_events IN ACCESS EXCLUSIVE MODE")
    op.execute(PREVIOUS_VALIDATOR)
    op.execute(f"DROP FUNCTION {PRUNE_SIGNATURE}")
    op.drop_index(INDEX_NAME, table_name="security_events", schema="auth")
    op.execute("REVOKE USAGE ON SCHEMA auth FROM sahl_security_maintenance")
